package com.hostelhub.controller;
import com.hostelhub.model.Complaint; import com.hostelhub.repository.ComplaintRepository; import com.hostelhub.service.RealtimeEventService; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import java.util.*;
@RestController @RequestMapping("/api/complaints") public class ComplaintController{private final ComplaintRepository repo;private final RealtimeEventService events;public ComplaintController(ComplaintRepository r,RealtimeEventService e){repo=r;events=e;}@GetMapping public List<Complaint> all(){return repo.findAll();}@PostMapping public Complaint add(@Valid @RequestBody Complaint c){Complaint x=repo.save(c);events.publish("complaint","New "+x.getPriority().toLowerCase()+" priority complaint from "+x.getStudentName());return x;}@PatchMapping("/{id}/approve") public Complaint approve(@PathVariable Long id){Complaint c=repo.findById(id).orElseThrow();c.setStatus("IN_PROGRESS");c=repo.save(c);events.publish("complaint","Complaint approved for "+c.getStudentName());return c;}@PatchMapping("/{id}/resolve") public Complaint resolve(@PathVariable Long id){Complaint c=repo.findById(id).orElseThrow();c.setStatus("RESOLVED");c=repo.save(c);events.publish("complaint","Complaint resolved for "+c.getStudentName());return c;}}
